# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make(last, first, section, email="a@b.org"):
    ident = last + first
    return Student(ident, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_sorted_by_name(self):
        rows = contact_rows(
            [make("Zed", "Al", "B"), make("Abe", "Bo", "A")]
        )
        self.assertTrue(rows[0].startswith("Abe, Bo"))
        self.assertTrue(rows[1].startswith("Zed, Al"))

    def test_columns_line_up(self):
        rows = contact_rows(
            [make("Longname", "Al", "A"),
             make("Li", "Bo", "B")]
        )
        self.assertEqual(
            rows,
            ["Li, Bo        B  a@b.org",
             "Longname, Al  A  a@b.org"]
        )

    def test_missing_email_names_student(self):
        students = [make("Lee", "Kim", "A", None)]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Lee, Kim", str(caught.exception))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
